using AwesomeAssertions;

namespace Tertius.Slop.Tests;

/// <summary>
/// Which files of a repository the slop metrics read (docs/plans/code-quality-tooling.md, decision 16): the C# files
/// under <c>src</c> that a person wrote, and not the build output or generated files. Each test builds a repository in
/// a new temporary folder.
/// </summary>
public sealed class CodebaseTests : IDisposable
{
    private readonly string root = Directory.CreateTempSubdirectory("tertius-slop-").FullName;

    public void Dispose() => Directory.Delete(root, recursive: true);

    [Fact]
    public void TheFilesUnderSrcAreReadWithPathsRelativeToTheRoot()
    {
        Write("src/Tertius.Core/World.cs", "class World { }");
        Write("src/Tertius.Core/Frames/FrameTree.cs", "class FrameTree { }");

        Codebase.Under(root).Files.Select(file => file.Path).Should().Equal(
            "src/Tertius.Core/Frames/FrameTree.cs", "src/Tertius.Core/World.cs");
    }

    [Fact]
    public void FilesOutsideSrcAreNotRead()
    {
        Write("src/A.cs", "class A { }");
        Write("tests/ATests.cs", "class ATests { }");
        Write("tools/Tool.cs", "class Tool { }");

        Codebase.Under(root).Files.Select(file => file.Path).Should().Equal("src/A.cs");
    }

    [Fact]
    public void FilesThatAreNotCSharpAreNotRead()
    {
        Write("src/A.cs", "class A { }");
        Write("src/Shaders/lighting.frag", "void main() { }");
        Write("src/Tertius.Core/Tertius.Core.csproj", "<Project />");

        Codebase.Under(root).Files.Select(file => file.Path).Should().Equal("src/A.cs");
    }

    [Fact]
    public void TheObjAndBinFoldersAreNotRead()
    {
        Write("src/Tertius.Core/A.cs", "class A { }");
        Write("src/Tertius.Core/obj/Checked/net11.0/AssemblyInfo.cs", "class Info { }");
        Write("src/Tertius.Core/bin/Checked/Copied.cs", "class Copied { }");

        Codebase.Under(root).Files.Select(file => file.Path).Should().Equal("src/Tertius.Core/A.cs");
    }

    [Fact]
    public void AFileWhoseNameEndsInGCsIsNotRead()
    {
        Write("src/A.cs", "class A { }");
        Write("src/A.g.cs", "partial class A { }");

        Codebase.Under(root).Files.Select(file => file.Path).Should().Equal("src/A.cs");
    }

    [Fact]
    public void AFileThatStartsWithTheAutoGeneratedMarkerIsNotRead()
    {
        Write("src/A.cs", "class A { }");
        Write("src/Generated.cs", """
                                  // <auto-generated/>
                                  class Generated { }
                                  """);
        Write("src/Tool.cs", """
                             //------------------------------------------------------------------------------
                             // <auto-generated>
                             //     This code was generated by a tool.
                             // </auto-generated>
                             //------------------------------------------------------------------------------
                             class Tool { }
                             """);

        Codebase.Under(root).Files.Select(file => file.Path).Should().Equal("src/A.cs");
    }

    [Fact]
    public void TheAutoGeneratedMarkerAfterTheFirstCodeDoesNotMakeAFileGenerated()
    {
        Write("src/A.cs", """
                          class A
                          {
                              // <auto-generated/> is the marker that the reader looks for.
                          }
                          """);

        Codebase.Under(root).Files.Select(file => file.Path).Should().Equal("src/A.cs");
    }

    [Fact]
    public void TheNamesOfTheTestsBenchmarksAndScriptsAreTheNamesOutsideSrc()
    {
        Write("src/Ship.cs", "static class Ship { }");
        Write("tests/Tertius.Core.Tests/ShipTests.cs", "class ShipTests { void F() => Ship.Fly(); }");
        Write("benchmarks/ShipBenchmarks.cs", "class ShipBenchmarks { void F() => Ship.Drift(); }");
        Write("scripts/launch.json", """{ "do": "post", "event": "Launch" }""");

        Codebase.Under(root).NamesOutside.Should().Contain(["Fly", "Drift", "Launch", "ShipTests"]);
    }

    [Fact]
    public void TheNamesOutsideSrcMatchWithoutCase()
    {
        IReadOnlySet<string> names = Codebase.NamesIn("""{ "do": "run", "ticks": 60 }""");

        (names.Contains("Run"), names.Contains("TICKS")).Should().Be((true, true));
    }

    [Fact]
    public void TheToolsDocsAndBuildOutputOutsideSrcAreNotReadForNames()
    {
        Write("src/Ship.cs", "static class Ship { }");
        Write("tools/Tool.cs", "class Tool { void F() => Ship.Sail(); }");
        Write("docs/plans/ship.md", "Ship.Dock moves the ship.");
        Write("tests/Tertius.Core.Tests/obj/Checked/Generated.cs", "class Generated { void F() => Ship.Hide(); }");
        Write("tests/Tertius.Core.Tests/notes.txt", "Ship.Turn");

        Codebase.Under(root).NamesOutside.Should().NotContain(["Sail", "Dock", "Hide", "Turn"]);
    }

    private void Write(string path, string text)
    {
        string full = Path.Combine(root, path);
        Directory.CreateDirectory(Path.GetDirectoryName(full) ?? root);
        File.WriteAllText(full, text);
    }
}
